#pragma once

#define OTA_AUTOMATION_STYLE \
    ".ota-automation{margin-top:1.3rem;padding-top:1.2rem;border-top:1px solid #dbe7ef}.ota-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem}.ota-heading h3{margin:0;font-size:1.05rem;color:var(--navy)}.ota-badge{padding:.25rem .65rem;border-radius:2rem;background:#edf2f6;color:#536477;font-size:.76rem;font-weight:750}.ota-badge[data-active=true]{background:#e7f3dd;color:#357b12}.ota-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem 1rem;margin-top:1rem}.ota-fields label{margin:0}.ota-wide{grid-column:1/-1}.ota-zone-tools{display:flex;align-items:center;justify-content:space-between;gap:1rem}.ota-zone-tools p{margin:0}.ota-zone-tools button{width:auto;margin:0;flex-shrink:0;background:#edf4fa;color:var(--navy);font-size:.8rem;padding:.55rem .8rem}.ota-save-row{display:flex;align-items:center;gap:1rem}.ota-save-row button{width:auto;margin:0}.ota-save-row p{margin:0}.ota-automation [hidden]{display:none!important}.ota-clock{margin-top:1.2rem;padding:.8rem 1rem;background:#f1f7fc;border:1px solid #dbe7ef;border-radius:.7rem}.ota-clock strong{display:block;margin-bottom:.25rem;color:var(--navy)}.ota-clock p{margin:0;font-size:.85rem;color:var(--muted)}.ota-history{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.9rem;margin:1rem 0 0}.ota-history dt{font-size:.76rem;color:var(--muted);font-weight:700}.ota-history dd{margin:.2rem 0 0;font-size:.88rem;overflow-wrap:anywhere}.ota-blocked{padding:.8rem 1rem;border-radius:.7rem;background:#fff5dc;color:#77521a;font-size:.86rem}@media(max-width:600px){.ota-fields,.ota-history{grid-template-columns:minmax(0,1fr)}.ota-zone-tools,.ota-save-row{align-items:stretch;flex-direction:column}.ota-zone-tools button,.ota-save-row button{width:100%}}"

#define OTA_AUTOMATION_HTML \
    "<section class=\"ota-automation\" aria-labelledby=\"ota-auto-title\"><div class=\"ota-heading\"><h3 id=\"ota-auto-title\">Automatische Updates</h3><span id=\"ota-auto-badge\" class=\"ota-badge\">Aus</span></div>" \
    "<p class=\"hint\">Die Ampel prüft und installiert selbstständig, auch bei geschlossener Verwaltungsseite.</p>" \
    "<form id=\"ota-automation-form\" class=\"ota-fields\"><label>Update-Automatik<select id=\"ota-auto-mode\"><option value=\"off\">Aus – manuell aktualisieren</option><option value=\"check\">Nur automatisch prüfen</option><option value=\"install\">Automatisch installieren</option></select></label>" \
    "<label>Nach Updates suchen<select id=\"ota-auto-interval\"><option value=\"1\">Jede Stunde</option><option value=\"6\">Alle 6 Stunden</option><option value=\"12\">Alle 12 Stunden</option><option value=\"24\" selected>Alle 24 Stunden</option></select></label>" \
    "<label id=\"ota-schedule-field\">Installation<select id=\"ota-auto-schedule\"><option value=\"daily\">Täglich zur Uhrzeit</option><option value=\"immediate\">Sobald ein Update verfügbar ist</option></select></label>" \
    "<label id=\"ota-time-field\">Installationszeit<input id=\"ota-auto-time\" type=\"time\" step=\"60\" value=\"03:00\" required></label>" \
    "<label class=\"ota-wide\">Zeitzone<select id=\"ota-auto-timezone\"><option value=\"\">Zeitzonen werden geladen …</option></select></label>" \
    "<div class=\"ota-zone-tools ota-wide\"><p id=\"ota-timezone-note\" class=\"hint\" role=\"status\"></p><button id=\"ota-browser-timezone\" type=\"button\">Vom Browser übernehmen</button></div>" \
    "<p id=\"ota-auto-notice\" class=\"hint ota-wide\">Automatische Updates starten die Ampel neu. Die Uhrzeit wird aus dem Internet synchronisiert; Sommer- und Winterzeit werden automatisch berücksichtigt.</p>" \
    "<div class=\"ota-save-row ota-wide\"><button id=\"ota-auto-save\" type=\"submit\">Update-Einstellungen speichern</button><p id=\"ota-settings-message\" class=\"hint\" role=\"status\" aria-live=\"polite\"></p></div></form>" \
    "<div class=\"ota-clock\"><strong id=\"ota-clock-time\">Internetzeit wird synchronisiert …</strong><p id=\"ota-auto-state\">Automatische Updates sind ausgeschaltet.</p></div>" \
    "<dl class=\"ota-history\"><div><dt>Letzte Prüfung</dt><dd id=\"ota-last-check\">–</dd></div><div><dt>Nächste Prüfung</dt><dd id=\"ota-next-check\">–</dd></div><div><dt>Nächste Installationszeit</dt><dd id=\"ota-next-install\">–</dd></div><div><dt>Letztes Ergebnis</dt><dd id=\"ota-last-result\">Noch nicht nach Updates gesucht.</dd></div><div><dt>Letztes Update</dt><dd id=\"ota-last-installed\">–</dd></div></dl>" \
    "<p id=\"ota-blocked-version\" class=\"ota-blocked\" hidden></p></section>"
